/* ============================================
   LearnForge — Corporate Website Styles
   Brand: #000000 / #E6FF32 / #7F2A23
   Typography: Plus Jakarta Sans + Inter
   ============================================ */

/* --- Custom Properties --- */
:root {
  --c-primary: #000000;
  --c-accent: #E6FF32;
  --c-burgundy: #7F2A23;
  --c-white: #FFFFFF;
  --c-bg: #F8FAFC;
  --c-bg-alt: #F1F5F9;
  --c-text: #1E293B;
  --c-text-secondary: #64748B;
  --c-border: #E2E8F0;
  --c-border-light: #F1F5F9;

  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  --container-max: 1200px;
  --section-py: 96px;
  --section-py-sm: 64px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  color: var(--c-text);
  background: var(--c-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  color: var(--c-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 3.5vw, 3rem); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p { margin-bottom: 1rem; }
p:last-child { margin-bottom: 0; }

.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--c-burgundy);
  margin-bottom: 0.75rem;
}

.section-title {
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--c-text-secondary);
  max-width: 640px;
  line-height: 1.7;
}

.section-subtitle.centered { margin-left: auto; margin-right: auto; }

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: var(--section-py) 0;
}

.section--sm {
  padding: var(--section-py-sm) 0;
}

.section--dark {
  background: var(--c-primary);
  color: var(--c-white);
}

.section--dark .section-title { color: var(--c-white); }
.section--dark .section-subtitle { color: rgba(255,255,255,0.7); }
.section--dark .section-label { color: var(--c-accent); }

.section--gray {
  background: var(--c-bg);
}

.section--accent {
  background: var(--c-accent);
  color: var(--c-primary);
}

.section--accent .section-title { color: var(--c-primary); }
.section--accent .section-subtitle { color: rgba(0,0,0,0.65); }

.text-center { text-align: center; }

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.gap-1 { gap: 8px; }
.gap-2 { gap: 16px; }
.gap-3 { gap: 24px; }
.gap-4 { gap: 32px; }

.grid { display: grid; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  transition: all var(--transition-base);
  white-space: nowrap;
  cursor: pointer;
}

.btn--primary {
  background: var(--c-accent);
  color: var(--c-primary);
}

.btn--primary:hover {
  background: #d9ed2d;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(230,255,50,0.3);
}

.btn--secondary {
  background: transparent;
  color: var(--c-text);
  border: 2px solid var(--c-border);
}

.btn--secondary:hover {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.btn--dark {
  background: var(--c-primary);
  color: var(--c-white);
}

.btn--dark:hover {
  background: #1a1a1a;
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn--white {
  background: var(--c-white);
  color: var(--c-primary);
}

.btn--white:hover {
  background: var(--c-bg);
  transform: translateY(-1px);
}

.btn--lg {
  padding: 16px 36px;
  font-size: 1rem;
}

.btn--sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

.btn svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-fast);
}

.btn:hover svg {
  transform: translateX(2px);
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--c-white);
  border-bottom: 1px solid var(--c-border-light);
  transition: box-shadow var(--transition-base);
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav__logo {
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--c-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav__logo-icon {
  width: 32px;
  height: 32px;
  background: var(--c-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav__link {
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--c-text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav__link:hover,
.nav__link.active {
  color: var(--c-primary);
}

.nav__link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--c-accent);
  border-radius: 1px;
}

.nav__cta {
  margin-left: 8px;
}

.nav__mobile-toggle {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--c-primary);
}

.nav__mobile-toggle:hover {
  background: var(--c-bg);
}

.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 99;
  background: var(--c-white);
  padding: 96px 24px 24px;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
}

.mobile-menu.open {
  display: flex;
}

.mobile-menu__link {
  display: block;
  padding: 16px 0;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--c-text);
  border-bottom: 1px solid var(--c-border-light);
}

.mobile-menu__cta {
  margin-top: 16px;
  text-align: center;
}

/* --- Hero --- */
.hero {
  padding: 80px 0 64px;
  overflow: hidden;
}

.hero__content {
  text-align: center;
  max-width: 800px;
  margin: 0 auto 48px;
}

.hero__title {
  margin-bottom: 20px;
}

.hero__title span {
  color: var(--c-burgundy);
}

.hero__subtitle {
  font-size: 1.1875rem;
  color: var(--c-text-secondary);
  line-height: 1.7;
  margin-bottom: 32px;
}

.hero__actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.hero__tab-toggle {
  display: inline-flex;
  background: var(--c-bg);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: 32px;
}

.hero__tab-btn {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-text-secondary);
  transition: all var(--transition-base);
}

.hero__tab-btn.active {
  background: var(--c-primary);
  color: var(--c-white);
  box-shadow: var(--shadow-md);
}

.hero__preview {
  position: relative;
  max-width: 960px;
  margin: 0 auto;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--c-border);
}

.hero__preview-panel {
  display: none;
  background: var(--c-bg);
  min-height: 400px;
}

.hero__preview-panel.active {
  display: block;
}

.hero__preview-mockup {
  padding: 32px;
}

.mockup-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--c-border);
}

.mockup-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.mockup-dot--red { background: #EF4444; }
.mockup-dot--yellow { background: #F59E0B; }
.mockup-dot--green { background: #10B981; }

.mockup-sidebar {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 24px;
  min-height: 300px;
}

.mockup-sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mockup-sidebar-item {
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.mockup-sidebar-item.active {
  background: var(--c-primary);
  color: var(--c-white);
}

.mockup-main-area {
  background: var(--c-white);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.mockup-main-area h4 {
  margin-bottom: 16px;
  font-size: 1rem;
}

.mockup-stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.mockup-stat-card {
  background: var(--c-bg);
  padding: 14px;
  border-radius: var(--radius-sm);
}

.mockup-stat-card .label {
  font-size: 0.6875rem;
  color: var(--c-text-secondary);
  margin-bottom: 4px;
}

.mockup-stat-card .value {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--c-primary);
}

.mockup-chart-placeholder {
  height: 120px;
  background: linear-gradient(180deg, var(--c-accent) 0%, transparent 100%);
  opacity: 0.3;
  border-radius: var(--radius-sm);
}

/* Student view mockup */
.mockup-student-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.mockup-student-course {
  background: var(--c-white);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  gap: 16px;
  align-items: center;
}

.mockup-course-thumb {
  width: 80px;
  height: 60px;
  background: linear-gradient(135deg, var(--c-accent), var(--c-burgundy));
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.mockup-course-info h4 {
  font-size: 0.9375rem;
  margin-bottom: 4px;
}

.mockup-course-info p {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.mockup-progress-bar {
  height: 6px;
  background: var(--c-border);
  border-radius: 3px;
  margin-top: 10px;
  overflow: hidden;
}

.mockup-progress-fill {
  height: 100%;
  background: var(--c-accent);
  border-radius: 3px;
}

/* --- Stats Bar --- */
.stats-bar {
  background: var(--c-primary);
  padding: 40px 0;
}

.stats-bar__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.stats-bar__item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stats-bar__value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--c-accent);
  line-height: 1.1;
}

.stats-bar__label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
  margin-top: 4px;
}

/* --- Cards --- */
.card {
  background: var(--c-white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--c-border);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  border-color: transparent;
  transform: translateY(-2px);
}

.card__icon {
  width: 48px;
  height: 48px;
  background: var(--c-bg);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--c-burgundy);
}

.card__icon svg {
  width: 24px;
  height: 24px;
}

.card__icon--accent {
  background: var(--c-accent);
  color: var(--c-primary);
}

.card__title {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.card__text {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

.card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--c-burgundy);
  margin-top: 16px;
  transition: gap var(--transition-fast);
}

.card__link:hover {
  gap: 10px;
}

.card__link svg {
  width: 16px;
  height: 16px;
}

/* --- Products Grid --- */
.products__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* --- Why Choose Us Tabs --- */
.why-tabs__nav {
  display: flex;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
  justify-content: center;
}

.why-tabs__btn {
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-text-secondary);
  border: 1px solid var(--c-border);
  transition: all var(--transition-base);
}

.why-tabs__btn:hover {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.why-tabs__btn.active {
  background: var(--c-primary);
  color: var(--c-white);
  border-color: var(--c-primary);
}

.why-tabs__panel {
  display: none;
}

.why-tabs__panel.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.why-tabs__features {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.why-tabs__feature {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.why-tabs__feature-icon {
  width: 40px;
  height: 40px;
  min-width: 40px;
  background: var(--c-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.why-tabs__feature-icon svg {
  width: 20px;
  height: 20px;
  color: var(--c-primary);
}

.why-tabs__feature h4 {
  margin-bottom: 4px;
  font-size: 1rem;
}

.why-tabs__feature p {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.5;
}

.why-tabs__visual {
  background: var(--c-bg);
  border-radius: var(--radius-lg);
  padding: 40px;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.why-tabs__visual-inner {
  width: 100%;
  max-width: 360px;
}

/* --- Global Scale --- */
.global-scale__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.global-scale__stats {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.global-scale__stat {
  display: flex;
  align-items: center;
  gap: 16px;
}

.global-scale__stat-value {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  color: var(--c-accent);
  min-width: 120px;
}

.global-scale__stat-label {
  color: rgba(255,255,255,0.8);
  font-size: 0.9375rem;
}

.global-scale__map {
  position: relative;
  aspect-ratio: 16 / 10;
  background: rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.global-scale__map svg {
  width: 80%;
  opacity: 0.3;
}

/* --- AI Automations --- */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.ai-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-base);
}

.ai-card:hover {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-md);
}

.ai-card__icon {
  width: 40px;
  height: 40px;
  background: var(--c-bg);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
  color: var(--c-burgundy);
}

.ai-card__icon svg {
  width: 20px;
  height: 20px;
}

.ai-card__title {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.ai-card__text {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
  line-height: 1.5;
}

/* --- Testimonials Carousel --- */
.testimonials {
  position: relative;
  overflow: hidden;
}

.testimonials__track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonials__slide {
  min-width: 100%;
  padding: 0 12px;
}

@media (min-width: 768px) {
  .testimonials__slide { min-width: 50%; }
}

@media (min-width: 1024px) {
  .testimonials__slide { min-width: 33.333%; }
}

.testimonial-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.section--gray .testimonial-card {
  background: var(--c-white);
}

.section--dark .testimonial-card {
  background: rgba(255,255,255,0.06);
  border-color: rgba(255,255,255,0.1);
}

.testimonial-card__quote {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--c-text);
  flex: 1;
  margin-bottom: 24px;
  position: relative;
  padding-left: 20px;
  border-left: 3px solid var(--c-accent);
}

.section--dark .testimonial-card__quote {
  color: rgba(255,255,255,0.9);
  border-left-color: var(--c-accent);
}

.testimonial-card__author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-card__avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--c-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: var(--c-burgundy);
}

.testimonial-card__name {
  font-weight: 600;
  font-size: 0.9375rem;
}

.testimonial-card__role {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.section--dark .testimonial-card__role {
  color: rgba(255,255,255,0.6);
}

.testimonial-card__badge {
  font-family: var(--font-heading);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--c-burgundy);
