/* ============================================
   LearnForge — Corporate Website Styles
   Brand: #000000 / #E6FF32 / #7F2A23
   Typography: Plus Jakarta Sans + Inter
   ============================================ */

/* --- Custom Properties --- */
:root {
  --c-primary: #000000;
  --c-accent: #E6FF32;
  --c-burgundy: #7F2A23;
  --c-white: #FFFFFF;
  --c-bg: #F8FAFC;
  --c-bg-alt: #F1F5F9;
  --c-text: #1E293B;
  --c-text-secondary: #64748B;
  --c-border: #E2E8F0;
  --c-border-light: #F1F5F9;

  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  --container-max: 1200px;
  --section-py: 96px;
  --section-py-sm: 64px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  color: var(--c-text);
  background: var(--c-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  color: var(--c-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 3.5vw, 3rem); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p { margin-bottom: 1rem; }
p:last-child { margin-bottom: 0; }

.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--c-burgundy);
  margin-bottom: 0.75rem;
}

.section-title {
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--c-text-secondary);
  max-width: 640px;
  line-height: 1.7;
}

.section-subtitle.centered { margin-left: auto; margin-right: auto; }

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: var(--section-py) 0;
}

.section--sm {
  padding: var(--section-py-sm) 0;
}

.section--dark {
  background: var(--c-primary);
  color: var(--c-white);
}

.section--dark .section-title { color: var(--c-white); }
.section--dark .section-subtitle { color: rgba(255,255,255,0.7); }
.section--dark .section-label { color: var(--c-accent); }

.section--gray {
  background: var(--c-bg);
}

.section--accent {
  background: var(--c-accent);
  color: var(--c-primary);
}

.section--accent .section-title { color: var(--c-primary); }
.section--accent .section-subtitle { color: rgba(0,0,0,0.65); }

.text-center { text-align: center; }

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.gap-1 { gap: 8px; }
.gap-2 { gap: 16px; }
.gap-3 { gap: 24px; }
.gap-4 { gap: 32px; }

.grid { display: grid; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  transition: all var(--transition-base);
  white-space: nowrap;
  cursor: pointer;
}

.btn--primary {
  background: var(--c-accent);
  color: var(--c-primary);
}

.btn--primary:hover {
  background: #d9ed2d;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(230,255,50,0.3);
}

.btn--secondary {
  background: transparent;
  color: var(--c-text);
  border: 2px solid var(--c-border);
}

.btn--secondary:hover {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.btn--dark {
  background: var(--c-primary);
  color: var(--c-white);
}

.btn--dark:hover {
  background: #1a1a1a;
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn--white {
  background: var(--c-white);
  color: var(--c-primary);
}

.btn--white:hover {
  background: var(--c-bg);
  transform: translateY(-1px);
}

.btn--lg {
  padding: 16px 36px;
  font-size: 1rem;
}

.btn--sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

.btn svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-fast);
}

.btn:hover svg {
  transform: translateX(2px);
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--c-white);
  border-bottom: 1px solid var(--c-border-light);
  transition: box-shadow var(--transition-base);
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav__logo {
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--c-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav__logo-icon {
  width: 32px;
  height: 32px;
  background: var(--c-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav__link {
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--c-text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav__link:hover,
.nav__link.active {
  color: var(--c-primary);
}

.nav__link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--c-accent);
  border-radius: 1px;
}

.nav__cta {
  margin-left: 8px;
}

.nav__mobile-toggle {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--c-primary);
}

.nav__mobile-toggle:hover {
  background: var(--c-bg);
}

.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 99;
  background: var(--c-white);
  padding: 96px 24px 24px;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
}

.mobile-menu.open {
  display: flex;
}

.mobile-menu__link {
  display: block;
  padding: 16px 0;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--c-text);
  border-bottom: 1px solid var(--c-border-light);
}

.mobile-menu__cta {
  margin-top: 16px;
  text-align: center;
}

/* --- Hero --- */
.hero {
  padding: 80px 0 64px;
  overflow: hidden;
}

.hero__content {
  text-align: center;
  max-width: 800px;
  margin: 0 auto 48px;
}

.hero__title {
  margin-bottom: 20px;
}

.hero__title span {
  color: var(--c-burgundy);
}

.hero__subtitle {
  font-size: 1.1875rem;
  color: var(--c-text-secondary);
  line-height: 1.7;
  margin-bottom: 32px;
}

.hero__actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.hero__tab-toggle {
  display: inline-flex;
  background: var(--c-bg);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: 32px;
}

.hero__tab-btn {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-text-secondary);
  transition: all var(--transition-base);
}

.hero__tab-btn.active {
  background: var(--c-primary);
  color: var(--c-white);
  box-shadow: var(--shadow-md);
}

.hero__preview {
  position: relative;
  max-width: 960px;
  margin: 0 auto;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--c-border);
}

.hero__preview-panel {
  display: none;
  background: var(--c-bg);
  min-height: 400px;
}

.hero__preview-panel.active {
  display: block;
}

.hero__preview-mockup {
  padding: 32px;
}

.mockup-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--c-border);
}

.mockup-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.mockup-dot--red { background: #EF4444; }
.mockup-dot--yellow { background: #F59E0B; }
.mockup-dot--green { background: #10B981; }

.mockup-sidebar {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 24px;
  min-height: 300px;
}

.mockup-sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mockup-sidebar-item {
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.mockup-sidebar-item.active {
  background: var(--c-primary);
  color: var(--c-white);
}

.mockup-main-area {
  background: var(--c-white);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.mockup-main-area h4 {
  margin-bottom: 16px;
  font-size: 1rem;
}

.mockup-stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.mockup-stat-card {
  background: var(--c-bg);
  padding: 14px;
  border-radius: var(--radius-sm);
}

.mockup-stat-card .label {
  font-size: 0.6875rem;
  color: var(--c-text-secondary);
  margin-bottom: 4px;
}

.mockup-stat-card .value {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--c-primary);
}

.mockup-chart-placeholder {
  height: 120px;
  background: linear-gradient(180deg, var(--c-accent) 0%, transparent 100%);
  opacity: 0.3;
  border-radius: var(--radius-sm);
}

/* Student view mockup */
.mockup-student-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.mockup-student-course {
  background: var(--c-white);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  gap: 16px;
  align-items: center;
}

.mockup-course-thumb {
  width: 80px;
  height: 60px;
  background: linear-gradient(135deg, var(--c-accent), var(--c-burgundy));
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.mockup-course-info h4 {
  font-size: 0.9375rem;
  margin-bottom: 4px;
}

.mockup-course-info p {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.mockup-progress-bar {
  height: 6px;
  background: var(--c-border);
  border-radius: 3px;
  margin-top: 10px;
  overflow: hidden;
}

.mockup-progress-fill {
  height: 100%;
  background: var(--c-accent);
  border-radius: 3px;
}

/* --- Stats Bar --- */
.stats-bar {
  background: var(--c-primary);
  padding: 40px 0;
}

.stats-bar__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.stats-bar__item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stats-bar__value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--c-accent);
  line-height: 1.1;
}

.stats-bar__label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
  margin-top: 4px;
}

/* --- Cards --- */
.card {
  background: var(--c-white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--c-border);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  border-color: transparent;
  transform: translateY(-2px);
}

.card__icon {
  width: 48px;
  height: 48px;
  background: var(--c-bg);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--c-burgundy);
}

.card__icon svg {
  width: 24px;
  height: 24px;
}

.card__icon--accent {
  background: var(--c-accent);
  color: var(--c-primary);
}

.card__title {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.card__text {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

.card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--c-burgundy);
  margin-top: 16px;
  transition: gap var(--transition-fast);
}

.card__link:hover {
  gap: 10px;
}

.card__link svg {
  width: 16px;
  height: 16px;
}

/* --- Products Grid --- */
.products__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* --- Why Choose Us Tabs --- */
.why-tabs__nav {
  display: flex;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
  justify-content: center;
}

.why-tabs__btn {
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-text-secondary);
  border: 1px solid var(--c-border);
  transition: all var(--transition-base);
}

.why-tabs__btn:hover {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.why-tabs__btn.active {
  background: var(--c-primary);
  color: var(--c-white);
  border-color: var(--c-primary);
}

.why-tabs__panel {
  display: none;
}

.why-tabs__panel.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.why-tabs__features {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.why-tabs__feature {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.why-tabs__feature-icon {
  width: 40px;
  height: 40px;
  min-width: 40px;
  background: var(--c-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.why-tabs__feature-icon svg {
  width: 20px;
  height: 20px;
  color: var(--c-primary);
}

.why-tabs__feature h4 {
  margin-bottom: 4px;
  font-size: 1rem;
}

.why-tabs__feature p {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.5;
}

.why-tabs__visual {
  background: var(--c-bg);
  border-radius: var(--radius-lg);
  padding: 40px;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.why-tabs__visual-inner {
  width: 100%;
  max-width: 360px;
}

/* --- Global Scale --- */
.global-scale__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.global-scale__stats {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.global-scale__stat {
  display: flex;
  align-items: center;
  gap: 16px;
}

.global-scale__stat-value {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  color: var(--c-accent);
  min-width: 120px;
}

.global-scale__stat-label {
  color: rgba(255,255,255,0.8);
  font-size: 0.9375rem;
}

.global-scale__map {
  position: relative;
  aspect-ratio: 16 / 10;
  background: rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.global-scale__map svg {
  width: 80%;
  opacity: 0.3;
}

/* --- AI Automations --- */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.ai-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-base);
}

.ai-card:hover {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-md);
}

.ai-card__icon {
  width: 40px;
  height: 40px;
  background: var(--c-bg);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
  color: var(--c-burgundy);
}

.ai-card__icon svg {
  width: 20px;
  height: 20px;
}

.ai-card__title {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.ai-card__text {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
  line-height: 1.5;
}

/* --- Testimonials Carousel --- */
.testimonials {
  position: relative;
  overflow: hidden;
}

.testimonials__track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonials__slide {
  min-width: 100%;
  padding: 0 12px;
}

@media (min-width: 768px) {
  .testimonials__slide { min-width: 50%; }
}

@media (min-width: 1024px) {
  .testimonials__slide { min-width: 33.333%; }
}

.testimonial-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.section--gray .testimonial-card {
  background: var(--c-white);
}

.section--dark .testimonial-card {
  background: rgba(255,255,255,0.06);
  border-color: rgba(255,255,255,0.1);
}

.testimonial-card__quote {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--c-text);
  flex: 1;
  margin-bottom: 24px;
  position: relative;
  padding-left: 20px;
  border-left: 3px solid var(--c-accent);
}

.section--dark .testimonial-card__quote {
  color: rgba(255,255,255,0.9);
  border-left-color: var(--c-accent);
}

.testimonial-card__author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-card__avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--c-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: var(--c-burgundy);
}

.testimonial-card__name {
  font-weight: 600;
  font-size: 0.9375rem;
}

.testimonial-card__role {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.section--dark .testimonial-card__role {
  color: rgba(255,255,255,0.6);
}

.testimonial-card__badge {
  font-family: var(--font-heading);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--c-burgundy);
  margin-bottom: 8px;
}

.section--dark .testimonial-card__badge {
  color: var(--c-accent);
}

.testimonials__nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 32px;
}

.testimonials__btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--c-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--c-text);
  transition: all var(--transition-fast);
  background: var(--c-white);
}

.testimonials__btn:hover {
  background: var(--c-primary);
  color: var(--c-white);
  border-color: var(--c-primary);
}

.section--dark .testimonials__btn {
  border-color: rgba(255,255,255,0.2);
  color: var(--c-white);
  background: rgba(255,255,255,0.06);
}

.section--dark .testimonials__btn:hover {
  background: var(--c-accent);
  color: var(--c-primary);
  border-color: var(--c-accent);
}

.testimonials__btn svg {
  width: 18px;
  height: 18px;
}

.testimonials__dots {
  display: flex;
  gap: 6px;
}

.testimonials__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--c-border);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.testimonials__dot.active {
  background: var(--c-primary);
  width: 24px;
  border-radius: 4px;
}

.section--dark .testimonials__dot.active {
  background: var(--c-accent);
}

/* --- Pricing --- */
.pricing__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  align-items: start;
}

.pricing-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  position: relative;
  transition: all var(--transition-base);
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card--featured {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-card__badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--c-accent);
  color: var(--c-primary);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.pricing-card__name {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.pricing-card__price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 4px;
}

.pricing-card__price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--c-text-secondary);
}

.pricing-card__fee {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
  margin-bottom: 20px;
}

.pricing-card__features {
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 24px;
}

.pricing-card__feature {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.875rem;
  color: var(--c-text-secondary);
}

.pricing-card__feature svg {
  width: 18px;
  height: 18px;
  min-width: 18px;
  color: var(--c-burgundy);
  margin-top: 1px;
}

/* --- Integrations --- */
.integrations__grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.integration-item {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  padding: 20px 16px;
  text-align: center;
  transition: all var(--transition-base);
}

.integration-item:hover {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-sm);
}

.section--dark .integration-item {
  background: rgba(255,255,255,0.04);
  border-color: rgba(255,255,255,0.08);
}

.section--dark .integration-item:hover {
  border-color: var(--c-accent);
}

.integration-item__logo {
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.section--dark .integration-item__logo {
  color: rgba(255,255,255,0.7);
}

.integration-item__name {
  font-size: 0.75rem;
  color: var(--c-text-secondary);
}

.section--dark .integration-item__name {
  color: rgba(255,255,255,0.5);
}

/* --- FAQ Accordion --- */
.faq__list {
  max-width: 768px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.faq-item {
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color var(--transition-base);
}

.faq-item.open {
  border-color: var(--c-accent);
}

.faq-item__question {
  width: 100%;
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--c-text);
  text-align: left;
  cursor: pointer;
  background: var(--c-white);
  transition: background var(--transition-fast);
}

.faq-item__question:hover {
  background: var(--c-bg);
}

.faq-item__icon {
  width: 24px;
  height: 24px;
  min-width: 24px;
  transition: transform var(--transition-base);
  color: var(--c-text-secondary);
}

.faq-item.open .faq-item__icon {
  transform: rotate(45deg);
  color: var(--c-burgundy);
}

.faq-item__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-item.open .faq-item__answer {
  max-height: 300px;
}

.faq-item__answer-inner {
  padding: 0 24px 20px;
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* --- CTA Banner --- */
.cta-banner {
  text-align: center;
  padding: 80px 0;
}

.cta-banner__title {
  margin-bottom: 16px;
}

.cta-banner__subtitle {
  font-size: 1.125rem;
  color: var(--c-text-secondary);
  max-width: 520px;
  margin: 0 auto 32px;
}

.section--dark .cta-banner__subtitle {
  color: rgba(255,255,255,0.7);
}

.section--accent .cta-banner__subtitle {
  color: rgba(0,0,0,0.65);
}

.cta-banner__actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

/* --- Social Proof --- */
.social-proof__logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
  opacity: 0.5;
}

.social-proof__logo {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--c-text-secondary);
}

/* --- Tools Grid --- */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}

.tools-grid__category {
  margin-bottom: 8px;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--c-burgundy);
}

.tools-grid__list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tools-grid__item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.875rem;
  color: var(--c-text-secondary);
  padding: 8px 12px;
  background: var(--c-white);
  border-radius: var(--radius-sm);
  border: 1px solid var(--c-border);
}

.tools-grid__item svg {
  width: 16px;
  height: 16px;
  color: var(--c-burgundy);
  min-width: 16px;
}

/* --- Value Proposition Cards --- */
.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

/* --- Three Steps --- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}

.steps-grid::before {
  content: '';
  position: absolute;
  top: 48px;
  left: 16.67%;
  right: 16.67%;
  height: 2px;
  background: var(--c-border);
  z-index: 0;
}

.step-card {
  text-align: center;
  position: relative;
  z-index: 1;
}

.step-card__number {
  width: 64px;
  height: 64px;
  background: var(--c-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--c-primary);
  margin: 0 auto 20px;
}

.step-card__title {
  margin-bottom: 8px;
}

.step-card__text {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* --- File Types --- */
.file-types__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.file-type-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: all var(--transition-base);
}

.file-type-item:hover {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-sm);
}

.file-type-item svg {
  width: 20px;
  height: 20px;
  color: var(--c-burgundy);
  min-width: 20px;
}

/* --- Spotlight Cards --- */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.spotlight-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-base);
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
}

.spotlight-card__image {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--c-accent), var(--c-burgundy));
  border-radius: var(--radius-md);
  margin-bottom: 16px;
}

.spotlight-card__title {
  margin-bottom: 8px;
}

.spotlight-card__text {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* --- Resources --- */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.resource-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition-base);
}

.resource-card:hover {
  box-shadow: var(--shadow-lg);
}

.resource-card__tag {
  font-family: var(--font-heading);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--c-burgundy);
  margin-bottom: 8px;
}

.resource-card__title {
  margin-bottom: 8px;
  font-size: 1.0625rem;
}

.resource-card__text {
  color: var(--c-text-secondary);
  font-size: 0.875rem;
  line-height: 1.6;
}

.resource-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-burgundy);
  margin-top: 12px;
  transition: gap var(--transition-fast);
}

.resource-card__link:hover { gap: 10px; }
.resource-card__link svg { width: 14px; height: 14px; }

/* --- Membership Highlight --- */
.membership-highlight {
  background: linear-gradient(135deg, var(--c-primary) 0%, #1a1a2e 100%);
  border-radius: var(--radius-xl);
  padding: 64px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.membership-highlight::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(230,255,50,0.08) 0%, transparent 60%);
}

.membership-highlight__stat {
  font-family: var(--font-heading);
  font-size: clamp(3rem, 6vw, 4.5rem);
  font-weight: 800;
  color: var(--c-accent);
  line-height: 1;
  margin-bottom: 8px;
}

.membership-highlight__label {
  font-size: 1.125rem;
  color: rgba(255,255,255,0.8);
  margin-bottom: 32px;
}

/* --- Product Demo Accordion --- */
.product-demo {
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.product-demo__header {
  width: 100%;
  padding: 24px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--c-text);
  cursor: pointer;
  background: var(--c-white);
}

.product-demo__header:hover {
  background: var(--c-bg);
}

.product-demo__chevron {
  width: 24px;
  height: 24px;
  transition: transform var(--transition-base);
  color: var(--c-text-secondary);
}

.product-demo.open .product-demo__chevron {
  transform: rotate(180deg);
}

.product-demo__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.product-demo.open .product-demo__content {
  max-height: 500px;
}

.product-demo__content-inner {
  padding: 0 32px 32px;
}

/* --- Footer --- */
.footer {
  background: var(--c-primary);
  color: var(--c-white);
  padding: 64px 0 32px;
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer__brand {
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 800;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.footer__brand-icon {
  width: 28px;
  height: 28px;
  background: var(--c-accent);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.footer__desc {
  color: rgba(255,255,255,0.6);
  font-size: 0.9375rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer__heading {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.4);
  margin-bottom: 16px;
}

.footer__links {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer__link {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
}

.footer__link:hover {
  color: var(--c-accent);
}

.footer__bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer__copyright {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

.footer__socials {
  display: flex;
  gap: 16px;
}

.footer__social {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.5);
  transition: all var(--transition-fast);
}

.footer__social:hover {
  background: rgba(255,255,255,0.1);
  color: var(--c-accent);
}

.footer__social svg {
  width: 18px;
  height: 18px;
}

/* --- Skip Link --- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 0;
  background: var(--c-primary);
  color: var(--c-white);
  padding: 12px 24px;
  z-index: 200;
  font-size: 0.9375rem;
  font-weight: 600;
}

.skip-link:focus {
  top: 0;
}

/* --- Responsive --- */
@media (max-width: 1023px) {
  .products__grid { grid-template-columns: repeat(2, 1fr); }
  .pricing__grid { grid-template-columns: repeat(2, 1fr); }
  .ai-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-grid { grid-template-columns: repeat(3, 1fr); }
  .integrations__grid { grid-template-columns: repeat(4, 1fr); }
  .footer__grid { grid-template-columns: 2fr 1fr 1fr; }

  .why-tabs__panel.active {
    grid-template-columns: 1fr;
  }

  .why-tabs__visual { display: none; }

  .global-scale__grid { grid-template-columns: 1fr; }
}

@media (max-width: 767px) {
  :root {
    --section-py: 64px;
    --section-py-sm: 48px;
  }

  .nav__links,
  .nav__cta { display: none; }
  .nav__mobile-toggle { display: flex; }

  .hero { padding: 48px 0 40px; }

  .hero__actions { flex-direction: column; align-items: stretch; }
  .hero__actions .btn { justify-content: center; }

  .stats-bar__grid { grid-template-columns: 1fr; gap: 24px; }

  .products__grid { grid-template-columns: 1fr; }

  .why-tabs__nav { flex-direction: column; }
  .why-tabs__btn { width: 100%; text-align: center; }

  .ai-grid { grid-template-columns: 1fr; }

  .pricing__grid { grid-template-columns: 1fr; }
  .pricing-card--featured { transform: none; }

  .integrations__grid { grid-template-columns: repeat(3, 1fr); }

  .tools-grid { grid-template-columns: repeat(2, 1fr); }

  .value-grid { grid-template-columns: 1fr; }

  .steps-grid { grid-template-columns: 1fr; }
  .steps-grid::before { display: none; }

  .spotlight-grid { grid-template-columns: 1fr; }

  .resources-grid { grid-template-columns: 1fr; }

  .file-types__grid { grid-template-columns: repeat(2, 1fr); }

  .membership-highlight { padding: 40px 24px; }

  .footer__grid { grid-template-columns: 1fr 1fr; }
  .footer__bottom { flex-direction: column; gap: 16px; text-align: center; }

  .mockup-sidebar { grid-template-columns: 1fr; }
  .mockup-sidebar-nav { display: none; }

  .hero__preview { margin: 0 -12px; border-radius: 0; }
}

@media (max-width: 480px) {
  .integrations__grid { grid-template-columns: repeat(2, 1fr); }
  .footer__grid { grid-template-columns: 1fr; }
  .file-types__grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: 1fr; }
}

/* --- Reduced Motion --- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* --- Focus States --- */
:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: 2px;
}

button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: 2px;
}

/* ============================================
   LearnForge — Corporate Website Styles
   Brand: #000000 / #E6FF32 / #7F2A23
   Typography: Plus Jakarta Sans + Inter
   ============================================ */

/* --- Custom Properties --- */
:root {
  --c-primary: #000000;
  --c-accent: #E6FF32;
  --c-burgundy: #7F2A23;
  --c-white: #FFFFFF;
  --c-bg: #F8FAFC;
  --c-bg-alt: #F1F5F9;
  --c-text: #1E293B;
  --c-text-secondary: #64748B;
  --c-border: #E2E8F0;
  --c-border-light: #F1F5F9;

  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  --container-max: 1200px;
  --section-py: 96px;
  --section-py-sm: 64px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  color: var(--c-text);
  background: var(--c-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  color: var(--c-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 3.5vw, 3rem); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p { margin-bottom: 1rem; }
p:last-child { margin-bottom: 0; }

.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--c-burgundy);
  margin-bottom: 0.75rem;
}

.section-title {
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--c-text-secondary);
  max-width: 640px;
  line-height: 1.7;
}

.section-subtitle.centered { margin-left: auto; margin-right: auto; }

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: var(--section-py) 0;
}

.section--sm {
  padding: var(--section-py-sm) 0;
}

.section--dark {
  background: var(--c-primary);
  color: var(--c-white);
}

.section--dark .section-title { color: var(--c-white); }
.section--dark .section-subtitle { color: rgba(255,255,255,0.7); }
.section--dark .section-label { color: var(--c-accent); }

.section--gray {
  background: var(--c-bg);
}

.section--accent {
  background: var(--c-accent);
  color: var(--c-primary);
}

.section--accent .section-title { color: var(--c-primary); }
.section--accent .section-subtitle { color: rgba(0,0,0,0.65); }

.text-center { text-align: center; }

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.gap-1 { gap: 8px; }
.gap-2 { gap: 16px; }
.gap-3 { gap: 24px; }
.gap-4 { gap: 32px; }

.grid { display: grid; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  transition: all var(--transition-base);
  white-space: nowrap;
  cursor: pointer;
}

.btn--primary {
  background: var(--c-accent);
  color: var(--c-primary);
}

.btn--primary:hover {
  background: #d9ed2d;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(230,255,50,0.3);
}

.btn--secondary {
  background: transparent;
  color: var(--c-text);
  border: 2px solid var(--c-border);
}

.btn--secondary:hover {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.btn--dark {
  background: var(--c-primary);
  color: var(--c-white);
}

.btn--dark:hover {
  background: #1a1a1a;
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn--white {
  background: var(--c-white);
  color: var(--c-primary);
}

.btn--white:hover {
  background: var(--c-bg);
  transform: translateY(-1px);
}

.btn--lg {
  padding: 16px 36px;
  font-size: 1rem;
}

.btn--sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

.btn svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-fast);
}

.btn:hover svg {
  transform: translateX(2px);
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--c-white);
  border-bottom: 1px solid var(--c-border-light);
  transition: box-shadow var(--transition-base);
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav__logo {
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--c-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav__logo-icon {
  width: 32px;
  height: 32px;
  background: var(--c-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav__link {
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--c-text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav__link:hover,
.nav__link.active {
  color: var(--c-primary);
}

.nav__link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--c-accent);
  border-radius: 1px;
}

.nav__cta {
  margin-left: 8px;
}

.nav__mobile-toggle {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--c-primary);
}

.nav__mobile-toggle:hover {
  background: var(--c-bg);
}

.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 99;
  background: var(--c-white);
  padding: 96px 24px 24px;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
}

.mobile-menu.open {
  display: flex;
}

.mobile-menu__link {
  display: block;
  padding: 16px 0;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--c-text);
  border-bottom: 1px solid var(--c-border-light);
}

.mobile-menu__cta {
  margin-top: 16px;
  text-align: center;
}

/* --- Hero --- */
.hero {
  padding: 80px 0 64px;
  overflow: hidden;
}

.hero__content {
  text-align: center;
  max-width: 800px;
  margin: 0 auto 48px;
}

.hero__title {
  margin-bottom: 20px;
}

.hero__title span {
  color: var(--c-burgundy);
}

.hero__subtitle {
  font-size: 1.1875rem;
  color: var(--c-text-secondary);
  line-height: 1.7;
  margin-bottom: 32px;
}

.hero__actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.hero__tab-toggle {
  display: inline-flex;
  background: var(--c-bg);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: 32px;
}

.hero__tab-btn {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-text-secondary);
  transition: all var(--transition-base);
}

.hero__tab-btn.active {
  background: var(--c-primary);
  color: var(--c-white);
  box-shadow: var(--shadow-md);
}

.hero__preview {
  position: relative;
  max-width: 960px;
  margin: 0 auto;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--c-border);
}

.hero__preview-panel {
  display: none;
  background: var(--c-bg);
  min-height: 400px;
}

.hero__preview-panel.active {
  display: block;
}

.hero__preview-mockup {
  padding: 32px;
}

.mockup-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--c-border);
}

.mockup-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.mockup-dot--red { background: #EF4444; }
.mockup-dot--yellow { background: #F59E0B; }
.mockup-dot--green { background: #10B981; }

.mockup-sidebar {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 24px;
  min-height: 300px;
}

.mockup-sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mockup-sidebar-item {
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.mockup-sidebar-item.active {
  background: var(--c-primary);
  color: var(--c-white);
}

.mockup-main-area {
  background: var(--c-white);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.mockup-main-area h4 {
  margin-bottom: 16px;
  font-size: 1rem;
}

.mockup-stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.mockup-stat-card {
  background: var(--c-bg);
  padding: 14px;
  border-radius: var(--radius-sm);
}

.mockup-stat-card .label {
  font-size: 0.6875rem;
  color: var(--c-text-secondary);
  margin-bottom: 4px;
}

.mockup-stat-card .value {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--c-primary);
}

.mockup-chart-placeholder {
  height: 120px;
  background: linear-gradient(180deg, var(--c-accent) 0%, transparent 100%);
  opacity: 0.3;
  border-radius: var(--radius-sm);
}

/* Student view mockup */
.mockup-student-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.mockup-student-course {
  background: var(--c-white);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  gap: 16px;
  align-items: center;
}

.mockup-course-thumb {
  width: 80px;
  height: 60px;
  background: linear-gradient(135deg, var(--c-accent), var(--c-burgundy));
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.mockup-course-info h4 {
  font-size: 0.9375rem;
  margin-bottom: 4px;
}

.mockup-course-info p {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.mockup-progress-bar {
  height: 6px;
  background: var(--c-border);
  border-radius: 3px;
  margin-top: 10px;
  overflow: hidden;
}

.mockup-progress-fill {
  height: 100%;
  background: var(--c-accent);
  border-radius: 3px;
}

/* --- Stats Bar --- */
.stats-bar {
  background: var(--c-primary);
  padding: 40px 0;
}

.stats-bar__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.stats-bar__item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stats-bar__value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--c-accent);
  line-height: 1.1;
}

.stats-bar__label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
  margin-top: 4px;
}

/* --- Cards --- */
.card {
  background: var(--c-white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--c-border);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  border-color: transparent;
  transform: translateY(-2px);
}

.card__icon {
  width: 48px;
  height: 48px;
  background: var(--c-bg);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--c-burgundy);
}

.card__icon svg {
  width: 24px;
  height: 24px;
}

.card__icon--accent {
  background: var(--c-accent);
  color: var(--c-primary);
}

.card__title {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.card__text {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

.card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--c-burgundy);
  margin-top: 16px;
  transition: gap var(--transition-fast);
}

.card__link:hover {
  gap: 10px;
}

.card__link svg {
  width: 16px;
  height: 16px;
}

/* --- Products Grid --- */
.products__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* --- Why Choose Us Tabs --- */
.why-tabs__nav {
  display: flex;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
  justify-content: center;
}

.why-tabs__btn {
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-text-secondary);
  border: 1px solid var(--c-border);
  transition: all var(--transition-base);
}

.why-tabs__btn:hover {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.why-tabs__btn.active {
  background: var(--c-primary);
  color: var(--c-white);
  border-color: var(--c-primary);
}

.why-tabs__panel {
  display: none;
}

.why-tabs__panel.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.why-tabs__features {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.why-tabs__feature {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.why-tabs__feature-icon {
  width: 40px;
  height: 40px;
  min-width: 40px;
  background: var(--c-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.why-tabs__feature-icon svg {
  width: 20px;
  height: 20px;
  color: var(--c-primary);
}

.why-tabs__feature h4 {
  margin-bottom: 4px;
  font-size: 1rem;
}

.why-tabs__feature p {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.5;
}

.why-tabs__visual {
  background: var(--c-bg);
  border-radius: var(--radius-lg);
  padding: 40px;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.why-tabs__visual-inner {
  width: 100%;
  max-width: 360px;
}

/* --- Global Scale --- */
.global-scale__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.global-scale__stats {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.global-scale__stat {
  display: flex;
  align-items: center;
  gap: 16px;
}

.global-scale__stat-value {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  color: var(--c-accent);
  min-width: 120px;
}

.global-scale__stat-label {
  color: rgba(255,255,255,0.8);
  font-size: 0.9375rem;
}

.global-scale__map {
  position: relative;
  aspect-ratio: 16 / 10;
  background: rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.global-scale__map svg {
  width: 80%;
  opacity: 0.3;
}

/* --- AI Automations --- */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.ai-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-base);
}

.ai-card:hover {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-md);
}

.ai-card__icon {
  width: 40px;
  height: 40px;
  background: var(--c-bg);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
  color: var(--c-burgundy);
}

.ai-card__icon svg {
  width: 20px;
  height: 20px;
}

.ai-card__title {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.ai-card__text {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
  line-height: 1.5;
}

/* --- Testimonials Carousel --- */
.testimonials {
  position: relative;
  overflow: hidden;
}

.testimonials__track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonials__slide {
  min-width: 100%;
  padding: 0 12px;
}

@media (min-width: 768px) {
  .testimonials__slide { min-width: 50%; }
}

@media (min-width: 1024px) {
  .testimonials__slide { min-width: 33.333%; }
}

.testimonial-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.section--gray .testimonial-card {
  background: var(--c-white);
}

.section--dark .testimonial-card {
  background: rgba(255,255,255,0.06);
  border-color: rgba(255,255,255,0.1);
}

.testimonial-card__quote {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--c-text);
  flex: 1;
  margin-bottom: 24px;
  position: relative;
  padding-left: 20px;
  border-left: 3px solid var(--c-accent);
}

.section--dark .testimonial-card__quote {
  color: rgba(255,255,255,0.9);
  border-left-color: var(--c-accent);
}

.testimonial-card__author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-card__avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--c-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: var(--c-burgundy);
}

.testimonial-card__name {
  font-weight: 600;
  font-size: 0.9375rem;
}

.testimonial-card__role {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.section--dark .testimonial-card__role {
  color: rgba(255,255,255,0.6);
}

.testimonial-card__badge {
  font-family: var(--font-heading);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--c-burgundy);
  margin-bottom: 8px;
}

.section--dark .testimonial-card__badge {
  color: var(--c-accent);
}

.testimonials__nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 32px;
}

.testimonials__btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--c-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--c-text);
  transition: all var(--transition-fast);
  background: var(--c-white);
}

.testimonials__btn:hover {
  background: var(--c-primary);
  color: var(--c-white);
  border-color: var(--c-primary);
}

.section--dark .testimonials__btn {
  border-color: rgba(255,255,255,0.2);
  color: var(--c-white);
  background: rgba(255,255,255,0.06);
}

.section--dark .testimonials__btn:hover {
  background: var(--c-accent);
  color: var(--c-primary);
  border-color: var(--c-accent);
}

.testimonials__btn svg {
  width: 18px;
  height: 18px;
}

.testimonials__dots {
  display: flex;
  gap: 6px;
}

.testimonials__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--c-border);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.testimonials__dot.active {
  background: var(--c-primary);
  width: 24px;
  border-radius: 4px;
}

.section--dark .testimonials__dot.active {
  background: var(--c-accent);
}

/* --- Pricing --- */
.pricing__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  align-items: start;
}

.pricing-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  position: relative;
  transition: all var(--transition-base);
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card--featured {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-card__badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--c-accent);
  color: var(--c-primary);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.pricing-card__name {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.pricing-card__price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 4px;
}

.pricing-card__price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--c-text-secondary);
}

.pricing-card__fee {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
  margin-bottom: 20px;
}

.pricing-card__features {
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 24px;
}

.pricing-card__feature {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.875rem;
  color: var(--c-text-secondary);
}

.pricing-card__feature svg {
  width: 18px;
  height: 18px;
  min-width: 18px;
  color: var(--c-burgundy);
  margin-top: 1px;
}

/* --- Integrations --- */
.integrations__grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.integration-item {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  padding: 20px 16px;
  text-align: center;
  transition: all var(--transition-base);
}

.integration-item:hover {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-sm);
}

.section--dark .integration-item {
  background: rgba(255,255,255,0.04);
  border-color: rgba(255,255,255,0.08);
}

.section--dark .integration-item:hover {
  border-color: var(--c-accent);
}

.integration-item__logo {
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.section--dark .integration-item__logo {
  color: rgba(255,255,255,0.7);
}

.integration-item__name {
  font-size: 0.75rem;
  color: var(--c-text-secondary);
}

.section--dark .integration-item__name {
  color: rgba(255,255,255,0.5);
}

/* --- FAQ Accordion --- */
.faq__list {
  max-width: 768px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.faq-item {
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color var(--transition-base);
}

.faq-item.open {
  border-color: var(--c-accent);
}

.faq-item__question {
  width: 100%;
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--c-text);
  text-align: left;
  cursor: pointer;
  background: var(--c-white);
  transition: background var(--transition-fast);
}

.faq-item__question:hover {
  background: var(--c-bg);
}

.faq-item__icon {
  width: 24px;
  height: 24px;
  min-width: 24px;
  transition: transform var(--transition-base);
  color: var(--c-text-secondary);
}

.faq-item.open .faq-item__icon {
  transform: rotate(45deg);
  color: var(--c-burgundy);
}

.faq-item__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-item.open .faq-item__answer {
  max-height: 300px;
}

.faq-item__answer-inner {
  padding: 0 24px 20px;
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* --- CTA Banner --- */
.cta-banner {
  text-align: center;
  padding: 80px 0;
}

.cta-banner__title {
  margin-bottom: 16px;
}

.cta-banner__subtitle {
  font-size: 1.125rem;
  color: var(--c-text-secondary);
  max-width: 520px;
  margin: 0 auto 32px;
}

.section--dark .cta-banner__subtitle {
  color: rgba(255,255,255,0.7);
}

.section--accent .cta-banner__subtitle {
  color: rgba(0,0,0,0.65);
}

.cta-banner__actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

/* --- Social Proof --- */
.social-proof__logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
  opacity: 0.5;
}

.social-proof__logo {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--c-text-secondary);
}

/* --- Tools Grid --- */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}

.tools-grid__category {
  margin-bottom: 8px;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--c-burgundy);
}

.tools-grid__list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tools-grid__item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.875rem;
  color: var(--c-text-secondary);
  padding: 8px 12px;
  background: var(--c-white);
  border-radius: var(--radius-sm);
  border: 1px solid var(--c-border);
}

.tools-grid__item svg {
  width: 16px;
  height: 16px;
  color: var(--c-burgundy);
  min-width: 16px;
}

/* --- Value Proposition Cards --- */
.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

/* --- Three Steps --- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}

.steps-grid::before {
  content: '';
  position: absolute;
  top: 48px;
  left: 16.67%;
  right: 16.67%;
  height: 2px;
  background: var(--c-border);
  z-index: 0;
}

.step-card {
  text-align: center;
  position: relative;
  z-index: 1;
}

.step-card__number {
  width: 64px;
  height: 64px;
  background: var(--c-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--c-primary);
  margin: 0 auto 20px;
}

.step-card__title {
  margin-bottom: 8px;
}

.step-card__text {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* --- File Types --- */
.file-types__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.file-type-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: all var(--transition-base);
}

.file-type-item:hover {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-sm);
}

.file-type-item svg {
  width: 20px;
  height: 20px;
  color: var(--c-burgundy);
  min-width: 20px;
}

/* --- Spotlight Cards --- */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.spotlight-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-base);
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
}

.spotlight-card__image {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--c-accent), var(--c-burgundy));
  border-radius: var(--radius-md);
  margin-bottom: 16px;
}

.spotlight-card__title {
  margin-bottom: 8px;
}

.spotlight-card__text {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* --- Resources --- */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.resource-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition-base);
}

.resource-card:hover {
  box-shadow: var(--shadow-lg);
}

.resource-card__tag {
  font-family: var(--font-heading);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--c-burgundy);
  margin-bottom: 8px;
}

.resource-card__title {
  margin-bottom: 8px;
  font-size: 1.0625rem;
}

.resource-card__text {
  color: var(--c-text-secondary);
  font-size: 0.875rem;
  line-height: 1.6;
}

.resource-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-burgundy);
  margin-top: 12px;
  transition: gap var(--transition-fast);
}

.resource-card__link:hover { gap: 10px; }
.resource-card__link svg { width: 14px; height: 14px; }

/* --- Membership Highlight --- */
.membership-highlight {
  background: linear-gradient(135deg, var(--c-primary) 0%, #1a1a2e 100%);
  border-radius: var(--radius-xl);
  padding: 64px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.membership-highlight::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(230,255,50,0.08) 0%, transparent 60%);
}

.membership-highlight__stat {
  font-family: var(--font-heading);
  font-size: clamp(3rem, 6vw, 4.5rem);
  font-weight: 800;
  color: var(--c-accent);
  line-height: 1;
  margin-bottom: 8px;
}

.membership-highlight__label {
  font-size: 1.125rem;
  color: rgba(255,255,255,0.8);
  margin-bottom: 32px;
}

/* --- Product Demo Accordion --- */
.product-demo {
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.product-demo__header {
  width: 100%;
  padding: 24px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--c-text);
  cursor: pointer;
  background: var(--c-white);
}

.product-demo__header:hover {
  background: var(--c-bg);
}

.product-demo__chevron {
  width: 24px;
  height: 24px;
  transition: transform var(--transition-base);
  color: var(--c-text-secondary);
}

.product-demo.open .product-demo__chevron {
  transform: rotate(180deg);
}

.product-demo__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.product-demo.open .product-demo__content {
  max-height: 500px;
}

.product-demo__content-inner {
  padding: 0 32px 32px;
}

/* --- Footer --- */
.footer {
  background: var(--c-primary);
  color: var(--c-white);
  padding: 64px 0 32px;
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer__brand {
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 800;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.footer__brand-icon {
  width: 28px;
  height: 28px;
  background: var(--c-accent);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.footer__desc {
  color: rgba(255,255,255,0.6);
  font-size: 0.9375rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer__heading {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.4);
  margin-bottom: 16px;
}

.footer__links {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer__link {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
}

.footer__link:hover {
  color: var(--c-accent);
}

.footer__bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer__copyright {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

.footer__socials {
  display: flex;
  gap: 16px;
}

.footer__social {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.5);
  transition: all var(--transition-fast);
}

.footer__social:hover {
  background: rgba(255,255,255,0.1);
  color: var(--c-accent);
}

.footer__social svg {
  width: 18px;
  height: 18px;
}

/* --- Skip Link --- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 0;
  background: var(--c-primary);
  color: var(--c-white);
  padding: 12px 24px;
  z-index: 200;
  font-size: 0.9375rem;
  font-weight: 600;
}

.skip-link:focus {
  top: 0;
}

/* --- Responsive --- */
@media (max-width: 1023px) {
  .products__grid { grid-template-columns: repeat(2, 1fr); }
  .pricing__grid { grid-template-columns: repeat(2, 1fr); }
  .ai-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-grid { grid-template-columns: repeat(3, 1fr); }
  .integrations__grid { grid-template-columns: repeat(4, 1fr); }
  .footer__grid { grid-template-columns: 2fr 1fr 1fr; }

  .why-tabs__panel.active {
    grid-template-columns: 1fr;
  }

  .why-tabs__visual { display: none; }

  .global-scale__grid { grid-template-columns: 1fr; }
}

@media (max-width: 767px) {
  :root {
    --section-py: 64px;
    --section-py-sm: 48px;
  }

  .nav__links,
  .nav__cta { display: none; }
  .nav__mobile-toggle { display: flex; }

  .hero { padding: 48px 0 40px; }

  .hero__actions { flex-direction: column; align-items: stretch; }
  .hero__actions .btn { justify-content: center; }

  .stats-bar__grid { grid-template-columns: 1fr; gap: 24px; }

  .products__grid { grid-template-columns: 1fr; }

  .why-tabs__nav { flex-direction: column; }
  .why-tabs__btn { width: 100%; text-align: center; }

  .ai-grid { grid-template-columns: 1fr; }

  .pricing__grid { grid-template-columns: 1fr; }
  .pricing-card--featured { transform: none; }

  .integrations__grid { grid-template-columns: repeat(3, 1fr); }

  .tools-grid { grid-template-columns: repeat(2, 1fr); }

  .value-grid { grid-template-columns: 1fr; }

  .steps-grid { grid-template-columns: 1fr; }
  .steps-grid::before { display: none; }

  .spotlight-grid { grid-template-columns: 1fr; }

  .resources-grid { grid-template-columns: 1fr; }

  .file-types__grid { grid-template-columns: repeat(2, 1fr); }

  .membership-highlight { padding: 40px 24px; }

  .footer__grid { grid-template-columns: 1fr 1fr; }
  .footer__bottom { flex-direction: column; gap: 16px; text-align: center; }

  .mockup-sidebar { grid-template-columns: 1fr; }
  .mockup-sidebar-nav { display: none; }

  .hero__preview { margin: 0 -12px; border-radius: 0; }
}

@media (max-width: 480px) {
  .integrations__grid { grid-template-columns: repeat(2, 1fr); }
  .footer__grid { grid-template-columns: 1fr; }
  .file-types__grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: 1fr; }
}

/* --- Reduced Motion --- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* --- Focus States --- */
:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: 2px;
}

button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: 2px;
}

raw_arguments.content:
/* ============================================
   LearnForge — Corporate Website Styles
   Brand: #000000 / #E6FF32 / #7F2A23
   Typography: Plus Jakarta Sans + Inter
   ============================================ */

/* --- Custom Properties --- */
:root {
  --c-primary: #000000;
  --c-accent: #E6FF32;
  --c-burgundy: #7F2A23;
  --c-white: #FFFFFF;
  --c-bg: #F8FAFC;
  --c-bg-alt: #F1F5F9;
  --c-text: #1E293B;
  --c-text-secondary: #64748B;
  --c-border: #E2E8F0;
  --c-border-light: #F1F5F9;

  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  --container-max: 1200px;
  --section-py: 96px;
  --section-py-sm: 64px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  color: var(--c-text);
  background: var(--c-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  color: var(--c-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 3.5vw, 3rem); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p { margin-bottom: 1rem; }
p:last-child { margin-bottom: 0; }

.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--c-burgundy);
  margin-bottom: 0.75rem;
}

.section-title {
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--c-text-secondary);
  max-width: 640px;
  line-height: 1.7;
}

.section-subtitle.centered { margin-left: auto; margin-right: auto; }

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: var(--section-py) 0;
}

.section--sm {
  padding: var(--section-py-sm) 0;
}

.section--dark {
  background: var(--c-primary);
  color: var(--c-white);
}

.section--dark .section-title { color: var(--c-white); }
.section--dark .section-subtitle { color: rgba(255,255,255,0.7); }
.section--dark .section-label { color: var(--c-accent); }

.section--gray {
  background: var(--c-bg);
}

.section--accent {
  background: var(--c-accent);
  color: var(--c-primary);
}

.section--accent .section-title { color: var(--c-primary); }
.section--accent .section-subtitle { color: rgba(0,0,0,0.65); }

.text-center { text-align: center; }

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.gap-1 { gap: 8px; }
.gap-2 { gap: 16px; }
.gap-3 { gap: 24px; }
.gap-4 { gap: 32px; }

.grid { display: grid; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  transition: all var(--transition-base);
  white-space: nowrap;
  cursor: pointer;
}

.btn--primary {
  background: var(--c-accent);
  color: var(--c-primary);
}

.btn--primary:hover {
  background: #d9ed2d;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(230,255,50,0.3);
}

.btn--secondary {
  background: transparent;
  color: var(--c-text);
  border: 2px solid var(--c-border);
}

.btn--secondary:hover {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.btn--dark {
  background: var(--c-primary);
  color: var(--c-white);
}

.btn--dark:hover {
  background: #1a1a1a;
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn--white {
  background: var(--c-white);
  color: var(--c-primary);
}

.btn--white:hover {
  background: var(--c-bg);
  transform: translateY(-1px);
}

.btn--lg {
  padding: 16px 36px;
  font-size: 1rem;
}

.btn--sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

.btn svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-fast);
}

.btn:hover svg {
  transform: translateX(2px);
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--c-white);
  border-bottom: 1px solid var(--c-border-light);
  transition: box-shadow var(--transition-base);
}

.nav.scrolled {
  box-shadow: var(--shadow-md);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav__logo {
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--c-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav__logo-icon {
  width: 32px;
  height: 32px;
  background: var(--c-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav__link {
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--c-text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav__link:hover,
.nav__link.active {
  color: var(--c-primary);
}

.nav__link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--c-accent);
  border-radius: 1px;
}

.nav__cta {
  margin-left: 8px;
}

.nav__mobile-toggle {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--c-primary);
}

.nav__mobile-toggle:hover {
  background: var(--c-bg);
}

.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 99;
  background: var(--c-white);
  padding: 96px 24px 24px;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
}

.mobile-menu.open {
  display: flex;
}

.mobile-menu__link {
  display: block;
  padding: 16px 0;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--c-text);
  border-bottom: 1px solid var(--c-border-light);
}

.mobile-menu__cta {
  margin-top: 16px;
  text-align: center;
}

/* --- Hero --- */
.hero {
  padding: 80px 0 64px;
  overflow: hidden;
}

.hero__content {
  text-align: center;
  max-width: 800px;
  margin: 0 auto 48px;
}

.hero__title {
  margin-bottom: 20px;
}

.hero__title span {
  color: var(--c-burgundy);
}

.hero__subtitle {
  font-size: 1.1875rem;
  color: var(--c-text-secondary);
  line-height: 1.7;
  margin-bottom: 32px;
}

.hero__actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.hero__tab-toggle {
  display: inline-flex;
  background: var(--c-bg);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: 32px;
}

.hero__tab-btn {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-text-secondary);
  transition: all var(--transition-base);
}

.hero__tab-btn.active {
  background: var(--c-primary);
  color: var(--c-white);
  box-shadow: var(--shadow-md);
}

.hero__preview {
  position: relative;
  max-width: 960px;
  margin: 0 auto;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--c-border);
}

.hero__preview-panel {
  display: none;
  background: var(--c-bg);
  min-height: 400px;
}

.hero__preview-panel.active {
  display: block;
}

.hero__preview-mockup {
  padding: 32px;
}

.mockup-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--c-border);
}

.mockup-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.mockup-dot--red { background: #EF4444; }
.mockup-dot--yellow { background: #F59E0B; }
.mockup-dot--green { background: #10B981; }

.mockup-sidebar {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 24px;
  min-height: 300px;
}

.mockup-sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mockup-sidebar-item {
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.mockup-sidebar-item.active {
  background: var(--c-primary);
  color: var(--c-white);
}

.mockup-main-area {
  background: var(--c-white);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.mockup-main-area h4 {
  margin-bottom: 16px;
  font-size: 1rem;
}

.mockup-stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.mockup-stat-card {
  background: var(--c-bg);
  padding: 14px;
  border-radius: var(--radius-sm);
}

.mockup-stat-card .label {
  font-size: 0.6875rem;
  color: var(--c-text-secondary);
  margin-bottom: 4px;
}

.mockup-stat-card .value {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--c-primary);
}

.mockup-chart-placeholder {
  height: 120px;
  background: linear-gradient(180deg, var(--c-accent) 0%, transparent 100%);
  opacity: 0.3;
  border-radius: var(--radius-sm);
}

/* Student view mockup */
.mockup-student-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.mockup-student-course {
  background: var(--c-white);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  gap: 16px;
  align-items: center;
}

.mockup-course-thumb {
  width: 80px;
  height: 60px;
  background: linear-gradient(135deg, var(--c-accent), var(--c-burgundy));
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.mockup-course-info h4 {
  font-size: 0.9375rem;
  margin-bottom: 4px;
}

.mockup-course-info p {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.mockup-progress-bar {
  height: 6px;
  background: var(--c-border);
  border-radius: 3px;
  margin-top: 10px;
  overflow: hidden;
}

.mockup-progress-fill {
  height: 100%;
  background: var(--c-accent);
  border-radius: 3px;
}

/* --- Stats Bar --- */
.stats-bar {
  background: var(--c-primary);
  padding: 40px 0;
}

.stats-bar__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.stats-bar__item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stats-bar__value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--c-accent);
  line-height: 1.1;
}

.stats-bar__label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
  margin-top: 4px;
}

/* --- Cards --- */
.card {
  background: var(--c-white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--c-border);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  border-color: transparent;
  transform: translateY(-2px);
}

.card__icon {
  width: 48px;
  height: 48px;
  background: var(--c-bg);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--c-burgundy);
}

.card__icon svg {
  width: 24px;
  height: 24px;
}

.card__icon--accent {
  background: var(--c-accent);
  color: var(--c-primary);
}

.card__title {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.card__text {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

.card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--c-burgundy);
  margin-top: 16px;
  transition: gap var(--transition-fast);
}

.card__link:hover {
  gap: 10px;
}

.card__link svg {
  width: 16px;
  height: 16px;
}

/* --- Products Grid --- */
.products__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* --- Why Choose Us Tabs --- */
.why-tabs__nav {
  display: flex;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
  justify-content: center;
}

.why-tabs__btn {
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-text-secondary);
  border: 1px solid var(--c-border);
  transition: all var(--transition-base);
}

.why-tabs__btn:hover {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.why-tabs__btn.active {
  background: var(--c-primary);
  color: var(--c-white);
  border-color: var(--c-primary);
}

.why-tabs__panel {
  display: none;
}

.why-tabs__panel.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.why-tabs__features {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.why-tabs__feature {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.why-tabs__feature-icon {
  width: 40px;
  height: 40px;
  min-width: 40px;
  background: var(--c-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.why-tabs__feature-icon svg {
  width: 20px;
  height: 20px;
  color: var(--c-primary);
}

.why-tabs__feature h4 {
  margin-bottom: 4px;
  font-size: 1rem;
}

.why-tabs__feature p {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.5;
}

.why-tabs__visual {
  background: var(--c-bg);
  border-radius: var(--radius-lg);
  padding: 40px;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.why-tabs__visual-inner {
  width: 100%;
  max-width: 360px;
}

/* --- Global Scale --- */
.global-scale__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.global-scale__stats {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.global-scale__stat {
  display: flex;
  align-items: center;
  gap: 16px;
}

.global-scale__stat-value {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  color: var(--c-accent);
  min-width: 120px;
}

.global-scale__stat-label {
  color: rgba(255,255,255,0.8);
  font-size: 0.9375rem;
}

.global-scale__map {
  position: relative;
  aspect-ratio: 16 / 10;
  background: rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.global-scale__map svg {
  width: 80%;
  opacity: 0.3;
}

/* --- AI Automations --- */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.ai-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-base);
}

.ai-card:hover {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-md);
}

.ai-card__icon {
  width: 40px;
  height: 40px;
  background: var(--c-bg);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
  color: var(--c-burgundy);
}

.ai-card__icon svg {
  width: 20px;
  height: 20px;
}

.ai-card__title {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.ai-card__text {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
  line-height: 1.5;
}

/* --- Testimonials Carousel --- */
.testimonials {
  position: relative;
  overflow: hidden;
}

.testimonials__track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonials__slide {
  min-width: 100%;
  padding: 0 12px;
}

@media (min-width: 768px) {
  .testimonials__slide { min-width: 50%; }
}

@media (min-width: 1024px) {
  .testimonials__slide { min-width: 33.333%; }
}

.testimonial-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.section--gray .testimonial-card {
  background: var(--c-white);
}

.section--dark .testimonial-card {
  background: rgba(255,255,255,0.06);
  border-color: rgba(255,255,255,0.1);
}

.testimonial-card__quote {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--c-text);
  flex: 1;
  margin-bottom: 24px;
  position: relative;
  padding-left: 20px;
  border-left: 3px solid var(--c-accent);
}

.section--dark .testimonial-card__quote {
  color: rgba(255,255,255,0.9);
  border-left-color: var(--c-accent);
}

.testimonial-card__author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-card__avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--c-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: var(--c-burgundy);
}

.testimonial-card__name {
  font-weight: 600;
  font-size: 0.9375rem;
}

.testimonial-card__role {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.section--dark .testimonial-card__role {
  color: rgba(255,255,255,0.6);
}

.testimonial-card__badge {
  font-family: var(--font-heading);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--c-burgundy);
  margin-bottom: 8px;
}

.section--dark .testimonial-card__badge {
  color: var(--c-accent);
}

.testimonials__nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 32px;
}

.testimonials__btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--c-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--c-text);
  transition: all var(--transition-fast);
  background: var(--c-white);
}

.testimonials__btn:hover {
  background: var(--c-primary);
  color: var(--c-white);
  border-color: var(--c-primary);
}

.section--dark .testimonials__btn {
  border-color: rgba(255,255,255,0.2);
  color: var(--c-white);
  background: rgba(255,255,255,0.06);
}

.section--dark .testimonials__btn:hover {
  background: var(--c-accent);
  color: var(--c-primary);
  border-color: var(--c-accent);
}

.testimonials__btn svg {
  width: 18px;
  height: 18px;
}

.testimonials__dots {
  display: flex;
  gap: 6px;
}

.testimonials__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--c-border);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.testimonials__dot.active {
  background: var(--c-primary);
  width: 24px;
  border-radius: 4px;
}

.section--dark .testimonials__dot.active {
  background: var(--c-accent);
}

/* --- Pricing --- */
.pricing__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  align-items: start;
}

.pricing-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  position: relative;
  transition: all var(--transition-base);
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card--featured {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-card__badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--c-accent);
  color: var(--c-primary);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.pricing-card__name {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.pricing-card__price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 4px;
}

.pricing-card__price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--c-text-secondary);
}

.pricing-card__fee {
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
  margin-bottom: 20px;
}

.pricing-card__features {
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 24px;
}

.pricing-card__feature {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.875rem;
  color: var(--c-text-secondary);
}

.pricing-card__feature svg {
  width: 18px;
  height: 18px;
  min-width: 18px;
  color: var(--c-burgundy);
  margin-top: 1px;
}

/* --- Integrations --- */
.integrations__grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.integration-item {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  padding: 20px 16px;
  text-align: center;
  transition: all var(--transition-base);
}

.integration-item:hover {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-sm);
}

.section--dark .integration-item {
  background: rgba(255,255,255,0.04);
  border-color: rgba(255,255,255,0.08);
}

.section--dark .integration-item:hover {
  border-color: var(--c-accent);
}

.integration-item__logo {
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.8125rem;
  color: var(--c-text-secondary);
}

.section--dark .integration-item__logo {
  color: rgba(255,255,255,0.7);
}

.integration-item__name {
  font-size: 0.75rem;
  color: var(--c-text-secondary);
}

.section--dark .integration-item__name {
  color: rgba(255,255,255,0.5);
}

/* --- FAQ Accordion --- */
.faq__list {
  max-width: 768px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.faq-item {
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color var(--transition-base);
}

.faq-item.open {
  border-color: var(--c-accent);
}

.faq-item__question {
  width: 100%;
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--c-text);
  text-align: left;
  cursor: pointer;
  background: var(--c-white);
  transition: background var(--transition-fast);
}

.faq-item__question:hover {
  background: var(--c-bg);
}

.faq-item__icon {
  width: 24px;
  height: 24px;
  min-width: 24px;
  transition: transform var(--transition-base);
  color: var(--c-text-secondary);
}

.faq-item.open .faq-item__icon {
  transform: rotate(45deg);
  color: var(--c-burgundy);
}

.faq-item__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-item.open .faq-item__answer {
  max-height: 300px;
}

.faq-item__answer-inner {
  padding: 0 24px 20px;
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* --- CTA Banner --- */
.cta-banner {
  text-align: center;
  padding: 80px 0;
}

.cta-banner__title {
  margin-bottom: 16px;
}

.cta-banner__subtitle {
  font-size: 1.125rem;
  color: var(--c-text-secondary);
  max-width: 520px;
  margin: 0 auto 32px;
}

.section--dark .cta-banner__subtitle {
  color: rgba(255,255,255,0.7);
}

.section--accent .cta-banner__subtitle {
  color: rgba(0,0,0,0.65);
}

.cta-banner__actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

/* --- Social Proof --- */
.social-proof__logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
  opacity: 0.5;
}

.social-proof__logo {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--c-text-secondary);
}

/* --- Tools Grid --- */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}

.tools-grid__category {
  margin-bottom: 8px;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--c-burgundy);
}

.tools-grid__list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tools-grid__item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.875rem;
  color: var(--c-text-secondary);
  padding: 8px 12px;
  background: var(--c-white);
  border-radius: var(--radius-sm);
  border: 1px solid var(--c-border);
}

.tools-grid__item svg {
  width: 16px;
  height: 16px;
