  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}

.steps-grid::before {
  content: '';
  position: absolute;
  top: 48px;
  left: 16.67%;
  right: 16.67%;
  height: 2px;
  background: var(--c-border);
  z-index: 0;
}

.step-card {
  text-align: center;
  position: relative;
  z-index: 1;
}

.step-card__number {
  width: 64px;
  height: 64px;
  background: var(--c-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--c-primary);
  margin: 0 auto 20px;
}

.step-card__title {
  margin-bottom: 8px;
}

.step-card__text {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* --- File Types --- */
.file-types__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.file-type-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: all var(--transition-base);
}

.file-type-item:hover {
  border-color: var(--c-accent);
  box-shadow: var(--shadow-sm);
}

.file-type-item svg {
  width: 20px;
  height: 20px;
  color: var(--c-burgundy);
  min-width: 20px;
}

/* --- Spotlight Cards --- */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.spotlight-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-base);
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
}

.spotlight-card__image {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--c-accent), var(--c-burgundy));
  border-radius: var(--radius-md);
  margin-bottom: 16px;
}

.spotlight-card__title {
  margin-bottom: 8px;
}

.spotlight-card__text {
  color: var(--c-text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* --- Resources --- */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.resource-card {
  background: var(--c-white);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition-base);
}

.resource-card:hover {
  box-shadow: var(--shadow-lg);
}

.resource-card__tag {
  font-family: var(--font-heading);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--c-burgundy);
  margin-bottom: 8px;
}

.resource-card__title {
  margin-bottom: 8px;
  font-size: 1.0625rem;
}

.resource-card__text {
  color: var(--c-text-secondary);
  font-size: 0.875rem;
  line-height: 1.6;
}

.resource-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--c-burgundy);
  margin-top: 12px;
  transition: gap var(--transition-fast);
}

.resource-card__link:hover { gap: 10px; }
.resource-card__link svg { width: 14px; height: 14px; }

/* --- Membership Highlight --- */
.membership-highlight {
  background: linear-gradient(135deg, var(--c-primary) 0%, #1a1a2e 100%);
  border-radius: var(--radius-xl);
  padding: 64px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.membership-highlight::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(230,255,50,0.08) 0%, transparent 60%);
}

.membership-highlight__stat {
  font-family: var(--font-heading);
  font-size: clamp(3rem, 6vw, 4.5rem);
  font-weight: 800;
  color: var(--c-accent);
  line-height: 1;
  margin-bottom: 8px;
}

.membership-highlight__label {
  font-size: 1.125rem;
  color: rgba(255,255,255,0.8);
  margin-bottom: 32px;
}

/* --- Product Demo Accordion --- */
.product-demo {
  border: 1px solid var(--c-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.product-demo__header {
  width: 100%;
  padding: 24px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--c-text);
  cursor: pointer;
  background: var(--c-white);
}

.product-demo__header:hover {
  background: var(--c-bg);
}

.product-demo__chevron {
  width: 24px;
  height: 24px;
  transition: transform var(--transition-base);
  color: var(--c-text-secondary);
}

.product-demo.open .product-demo__chevron {
  transform: rotate(180deg);
}

.product-demo__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.product-demo.open .product-demo__content {
  max-height: 500px;
}

.product-demo__content-inner {
  padding: 0 32px 32px;
}

/* --- Footer --- */
.footer {
  background: var(--c-primary);
  color: var(--c-white);
  padding: 64px 0 32px;
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
