.footer__brand {
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 800;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.footer__brand-icon {
  width: 28px;
  height: 28px;
  background: var(--c-accent);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.footer__desc {
  color: rgba(255,255,255,0.6);
  font-size: 0.9375rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer__heading {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.4);
  margin-bottom: 16px;
}

.footer__links {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer__link {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
}

.footer__link:hover {
  color: var(--c-accent);
}

.footer__bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer__copyright {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

.footer__socials {
  display: flex;
  gap: 16px;
}

.footer__social {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.5);
  transition: all var(--transition-fast);
}

.footer__social:hover {
  background: rgba(255,255,255,0.1);
  color: var(--c-accent);
}

.footer__social svg {
  width: 18px;
  height: 18px;
}

/* --- Skip Link --- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 0;
  background: var(--c-primary);
  color: var(--c-white);
  padding: 12px 24px;
  z-index: 200;
  font-size: 0.9375rem;
  font-weight: 600;
}

.skip-link:focus {
  top: 0;
}

/* --- Responsive --- */
@media (max-width: 1023px) {
  .products__grid { grid-template-columns: repeat(2, 1fr); }
  .pricing__grid { grid-template-columns: repeat(2, 1fr); }
  .ai-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-grid { grid-template-columns: repeat(3, 1fr); }
  .integrations__grid { grid-template-columns: repeat(4, 1fr); }
  .footer__grid { grid-template-columns: 2fr 1fr 1fr; }

  .why-tabs__panel.active {
    grid-template-columns: 1fr;
  }

  .why-tabs__visual { display: none; }

  .global-scale__grid { grid-template-columns: 1fr; }
}

@media (max-width: 767px) {
  :root {
    --section-py: 64px;
    --section-py-sm: 48px;
  }

  .nav__links,
  .nav__cta { display: none; }
  .nav__mobile-toggle { display: flex; }

  .hero { padding: 48px 0 40px; }

  .hero__actions { flex-direction: column; align-items: stretch; }
  .hero__actions .btn { justify-content: center; }

  .stats-bar__grid { grid-template-columns: 1fr; gap: 24px; }

  .products__grid { grid-template-columns: 1fr; }

  .why-tabs__nav { flex-direction: column; }
  .why-tabs__btn { width: 100%; text-align: center; }

  .ai-grid { grid-template-columns: 1fr; }

  .pricing__grid { grid-template-columns: 1fr; }
  .pricing-card--featured { transform: none; }

  .integrations__grid { grid-template-columns: repeat(3, 1fr); }

  .tools-grid { grid-template-columns: repeat(2, 1fr); }

  .value-grid { grid-template-columns: 1fr; }

  .steps-grid { grid-template-columns: 1fr; }
  .steps-grid::before { display: none; }

  .spotlight-grid { grid-template-columns: 1fr; }

  .resources-grid { grid-template-columns: 1fr; }

  .file-types__grid { grid-template-columns: repeat(2, 1fr); }

  .membership-highlight { padding: 40px 24px; }

  .footer__grid { grid-template-columns: 1fr 1fr; }
  .footer__bottom { flex-direction: column; gap: 16px; text-align: center; }

  .mockup-sidebar { grid-template-columns: 1fr; }
  .mockup-sidebar-nav { display: none; }

  .hero__preview { margin: 0 -12px; border-radius: 0; }
}

@media (max-width: 480px) {
  .integrations__grid { grid-template-columns: repeat(2, 1fr); }
  .footer__grid { grid-template-columns: 1fr; }
  .file-types__grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: 1fr; }
}

/* --- Reduced Motion --- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* --- Focus States --- */
:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: 2px;
}

button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: 2px;
}

